@Component("investmentAccount-handler")
@ProcessingGroup("investmentAccount-processing-group")
public class InvestmentAccountEventHandler {
	
	// core constructor
	InvestmentAccountEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInvestmentAccountEvent
     */
    @EventHandler
    public void handle( CreateInvestmentAccountEvent event) {
        entityManager.persist(new InvestmentAccount(event.getInvestmentAccountId(), event.getAccountNumber(), event.getBaseCurrency(), event.getBalance(), event.getPortfolio(), event.getTrades(), event.getOrders(), event.getAccountType(), event.getStatus()));
    }

    /*
     * @param	event UpdateInvestmentAccountEvent
     */
    @EventHandler
    public InvestmentAccount handle( UpdateInvestmentAccountEvent event) {
    	entityManager.merge(new InvestmentAccount(event.getInvestmentAccountId(), event.getAccountNumber(), event.getBaseCurrency(), event.getBalance(), event.getPortfolio(), event.getTrades(), event.getOrders(), event.getAccountType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteInvestmentAccountEvent
     */
    @EventHandler
    public void on( DeleteInvestmentAccountEvent event) {
    	InvestmentAccount entity = new InvestmentAccount();
   
    	// ------------------------------------------
    	// apply the InvestmentAccountId
    	// ------------------------------------------
    	entity.setInvestmentAccountId( event.getInvestmentAccountId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InvestmentAccountRepository investmentAccountEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InvestmentAccountEventHandler.class.getName());

}
